"""Anagram comparison utilities."""

import unicodedata


def is_anagram(a: str, b: str) -> bool:
    """Return True if `a` and `b` are anagrams of each other.

    Comparison ignores case, whitespace, and punctuation.
    """
    return _normalize(a) == _normalize(b)


def _normalize(s: str) -> str:
    chars = [c.lower() for c in s if _is_significant(c)]
    return sorted(chars)


def _is_significant(c: str) -> bool:
    category = unicodedata.category(c)
    return not (c.isspace() or category.startswith("P"))

