import unittest

from src.anagram import is_anagram


class TestIsAnagram(unittest.TestCase):
    def test_simple_anagram(self):
        self.assertTrue(is_anagram("listen", "silent"))

    def test_ignores_case(self):
        self.assertTrue(is_anagram("Listen", "Silent"))

    def test_ignores_whitespace(self):
        self.assertTrue(is_anagram("astronomer", "moon starer"))

    def test_ignores_punctuation(self):
        self.assertTrue(is_anagram("A gentleman!", "Elegant man"))

    def test_not_anagram(self):
        self.assertFalse(is_anagram("hello", "world"))

    def test_different_lengths_not_anagram(self):
        self.assertFalse(is_anagram("abc", "abcd"))

    def test_empty_strings(self):
        self.assertTrue(is_anagram("", ""))

    def test_punctuation_only_equals_empty(self):
        self.assertTrue(is_anagram("!!!", ""))


if __name__ == "__main__":
    unittest.main()

